<?php
namespace App\Http\Controllers;
use App\Models\OrderItem; use App\Models\ReturnRefundEvidence; use App\Models\ReturnRefundRequest; use App\Services\ReturnRefundService; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage;
class ReturnRefundController extends Controller {
 public function buyerIndex(Request $q){$this->buyer($q);return response()->json(ReturnRefundRequest::where('buyer_id',$q->user()->id)->latest()->get());}
 public function store(Request $q,OrderItem $item,ReturnRefundService $service){$this->buyer($q);$d=$q->validate(['type'=>'required|in:RETURN,REFUND','quantity'=>'required|integer','reason'=>'required|string|max:100','description'=>'required|string|max:5000']);return response()->json($service->submit($q->user(),$item,$d),201);}
 public function sellerRespond(Request $q,ReturnRefundRequest $returnRefundRequest,ReturnRefundService $service){$d=$q->validate(['recommendation'=>'required|in:APPROVE,REJECT','note'=>'required|string|max:5000']);return response()->json($service->sellerRespond($returnRefundRequest,$q->user(),$d));}
 public function decide(Request $q,ReturnRefundRequest $returnRefundRequest,ReturnRefundService $service){$d=$q->validate(['decision'=>'required|in:APPROVED,REJECTED','reason'=>'required|string|max:5000']);return response()->json($service->decide($returnRefundRequest,$q->user(),$d['decision'],$d['reason']));}
 public function evidence(Request $q,ReturnRefundRequest $returnRefundRequest){$this->access($q,$returnRefundRequest);abort_if(in_array($returnRefundRequest->status,['ADMIN_APPROVED','ADMIN_REJECTED']),422);$d=$q->validate(['file'=>'required|file|mimetypes:image/jpeg,image/png|max:5120','description'=>'nullable|string|max:500']);$f=$d['file'];$path=$f->store('return-refund-evidence/'.$returnRefundRequest->id,'local');return response()->json(ReturnRefundEvidence::create(['return_refund_request_id'=>$returnRefundRequest->id,'uploaded_by'=>$q->user()->id,'path'=>$path,'mime'=>$f->getMimeType(),'size'=>$f->getSize(),'description'=>$d['description']??null]),201);}
 public function showEvidence(Request $q,ReturnRefundRequest $returnRefundRequest,ReturnRefundEvidence $evidence){$this->access($q,$returnRefundRequest);abort_unless($evidence->return_refund_request_id===$returnRefundRequest->id,404);return Storage::disk('local')->download($evidence->path);}
 private function buyer(Request $q):void{abort_unless($q->user()?->isBuyer(),403);} private function access(Request $q,ReturnRefundRequest $r):void{$u=$q->user();abort_unless($u&&((int)$r->buyer_id===(int)$u->id||((int)$r->seller->user_id===(int)$u->id)||$u->isAdmin()),403);}
}
